import { vendorAssetHeaders } from '../utils/vendorAssetHeaders'

// CORS + Cache-Control for the same-origin third-party assets under
// /vendor/ (generated by modules/vendor-assets.ts). Rules and why:
// server/utils/vendorAssetHeaders.ts. The `request` hook runs before
// Nitro's static-asset handler, which sets no Cache-Control of its own
// for this directory.

export default defineNitroPlugin((nitroApp) => {
  nitroApp.hooks.hook('request', (event) => {
    const headers = vendorAssetHeaders(event.path)
    if (headers) setResponseHeaders(event, headers)
  })
})
